from __future__ import annotations
from fastapi import HTTPException, Request
from fastapi.responses import HTMLResponse
from .main import app
from .db import connect
from .adaptive_practice import build_adaptive_practice
from .student_security import resolve_student_code

@app.get("/api/student/portal")
def student_portal(request: Request, student_code: str | None = None):
    code=resolve_student_code(request, student_code)
    with connect() as con:
        st=con.execute("SELECT id,name,external_code FROM students WHERE external_code=%s",(code,)).fetchone()
        if not st: raise HTTPException(404,"كود الطالب غير صحيح")
        attempts=list(con.execute("""SELECT a.id,a.quiz_id,q.title quiz_title,a.score,a.max_score,a.completed_at,
          round(100.0*a.score/nullif(a.max_score,0),1) percentage
          FROM attempts a LEFT JOIN quizzes q ON q.id=a.quiz_id
          WHERE a.student_id=%s ORDER BY a.completed_at DESC NULLS LAST,a.id DESC LIMIT 10""",(st["id"],)).fetchall())
        errors=list(con.execute("""SELECT aa.question_id,q.text_verbatim,count(*) wrong_count,max(a.completed_at) last_wrong
          FROM attempt_answers aa JOIN attempts a ON a.id=aa.attempt_id JOIN questions q ON q.id=aa.question_id
          WHERE a.student_id=%s AND aa.is_correct=FALSE
          GROUP BY aa.question_id,q.text_verbatim ORDER BY wrong_count DESC,last_wrong DESC LIMIT 8""",(st["id"],)).fetchall())
        improvement=con.execute("""WITH x AS (
          SELECT a.id,a.completed_at,100.0*a.score/nullif(a.max_score,0) pct,
                 row_number() OVER(ORDER BY a.completed_at DESC NULLS LAST,a.id DESC) rn
          FROM attempts a WHERE a.student_id=%s AND a.max_score>0)
          SELECT max(pct) FILTER(WHERE rn=1) latest,max(pct) FILTER(WHERE rn=2) previous FROM x WHERE rn<=2""",(st["id"],)).fetchone()
        available=list(con.execute("""SELECT q.id,q.title,q.duration_minutes,q.quality_score,q.published_at,q.max_attempts,q.retry_wait_minutes,q.score_policy,
          s.name_ar subject_name,g.name_ar grade_name,cv.academic_year curriculum_year,cv.active curriculum_active,
          EXISTS(SELECT 1 FROM attempts a WHERE a.student_id=%s AND a.quiz_id=q.id AND a.completed_at IS NULL) has_open_attempt,
          (SELECT count(*) FROM attempts a WHERE a.student_id=%s AND a.quiz_id=q.id AND a.completed_at IS NOT NULL) attempts_used,
          (SELECT max(a.completed_at) FROM attempts a WHERE a.student_id=%s AND a.quiz_id=q.id AND a.completed_at IS NOT NULL) last_completed,
          (SELECT max(100.0*a.score/nullif(a.max_score,0)) FROM attempts a WHERE a.student_id=%s AND a.quiz_id=q.id AND a.completed_at IS NOT NULL) best_percentage,
          (SELECT 100.0*a.score/nullif(a.max_score,0) FROM attempts a WHERE a.student_id=%s AND a.quiz_id=q.id AND a.completed_at IS NOT NULL ORDER BY a.completed_at DESC,a.id DESC LIMIT 1) latest_percentage
          FROM quizzes q LEFT JOIN subjects s ON s.id=q.subject_id LEFT JOIN grade_levels g ON g.id=q.grade_level_id
          LEFT JOIN curriculum_versions cv ON cv.id=q.curriculum_version_id
          WHERE q.published=TRUE AND q.lifecycle_status='published'
          ORDER BY q.published_at DESC NULLS LAST,q.id DESC LIMIT 50""",(st["id"],st["id"],st["id"],st["id"],st["id"])).fetchall())
        current_curriculum=con.execute("""SELECT cv.id,cv.academic_year,cv.version_label,
          (SELECT count(*) FROM documents d WHERE d.curriculum_version_id=cv.id) source_documents,
          (SELECT count(*) FROM questions q WHERE q.curriculum_version_id=cv.id) total_questions,
          (SELECT count(*) FROM questions q WHERE q.curriculum_version_id=cv.id AND q.approved=TRUE) approved_questions,
          (SELECT count(*) FROM question_review_notes qr JOIN questions q ON q.id=qr.question_id WHERE q.curriculum_version_id=cv.id AND qr.status='open') qa_open,
          (SELECT count(*) FROM quizzes z WHERE z.curriculum_version_id=cv.id AND z.published=TRUE) published_quizzes
          FROM curriculum_versions cv
          WHERE cv.subject_id=1 AND cv.grade_level_id=6 AND cv.active=TRUE
          ORDER BY cv.id DESC LIMIT 1""").fetchone()
    from .analytics import _student_mastery,_remedial_progress,_learning_recommendations
    from .advanced_learning import build_learning_suite
    with connect() as con:
        mastery=_student_mastery(con,st["id"])
        remedial=_remedial_progress(con,st["id"],6)
        learning=_learning_recommendations(con,st["id"])
    adaptive=build_adaptive_practice(st["id"],10)
    suite=build_learning_suite(code)
    latest=float(improvement["latest"]) if improvement and improvement["latest"] is not None else None
    previous=float(improvement["previous"]) if improvement and improvement["previous"] is not None else None
    return {"student":st,"attempts":attempts,"errors":errors,"available_quizzes":available,"current_curriculum":current_curriculum,"mastery":mastery,"remedial_progress":remedial,"learning_recommendations":learning,"adaptive":adaptive,"learning_suite":suite,
            "improvement":{"latest":latest,"previous":previous,"delta":round(latest-previous,1) if latest is not None and previous is not None else None}}

PAGE=r'''<!doctype html><html lang=ar dir=rtl><meta name=viewport content="width=device-width,initial-scale=1"><title>بوابة الطالب</title><style>
:root{--bg:#f5f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#e5e7eb;--brand:#2447a8}*{box-sizing:border-box}body{font-family:system-ui;background:var(--bg);color:var(--text);margin:0}main{max-width:1050px;margin:auto;padding:18px 18px 90px}.box{background:var(--card);border-radius:16px;padding:16px;margin:12px 0;box-shadow:0 3px 14px #0001}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px}.card{border:1px solid var(--line);border-radius:12px;padding:12px}.big{font-size:26px;font-weight:800}.muted{color:var(--muted)}.good{color:#067647}.bad{color:#b42318}.warn{color:#b54708}.hero{background:linear-gradient(135deg,#fff,#eef3ff)}.actions{display:flex;gap:8px;flex-wrap:wrap}.actions button,.primary{background:var(--brand);color:#fff;border-color:var(--brand)}input,button{padding:11px;border:1px solid #ccd2dd;border-radius:9px;font:inherit}button{cursor:pointer}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #eee;text-align:right}.mini-nav{display:none}.section-title{display:flex;justify-content:space-between;gap:10px;align-items:center}.pill{display:inline-block;padding:5px 9px;border-radius:999px;background:#eef3ff;color:#2447a8;font-size:12px;font-weight:700}@media(max-width:650px){main{padding:12px 12px 88px}.box{border-radius:13px;padding:13px}.grid{grid-template-columns:1fr 1fr}.big{font-size:22px}table{font-size:12px}.mini-nav{display:grid;grid-template-columns:repeat(4,1fr);position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #e5e7eb;z-index:20;padding:7px 5px}.mini-nav button{border:0;background:none;padding:7px 3px;font-size:12px;color:#344054}.hero input{width:100%;margin-bottom:8px}.hero>button{width:100%}}@media(max-width:400px){.grid{grid-template-columns:1fr}}
</style><main>
<div class="box hero"><h1>بوابة الطالب</h1><p class=muted>خطة مذاكرة، مراجعة، اختبارات، وقياس جاهزية في مكان واحد.</p><input id=code placeholder="كود الطالب"><button class=primary onclick=load()>دخول</button><div id=msg class=muted></div></div><div id=content></div>
<nav class=mini-nav><button onclick="go('overview')">الرئيسية</button><button onclick="go('plan')">الخطة</button><button onclick="go('quizzes')">الاختبارات</button><button onclick="go('progress')">التقدم</button></nav>
<script>function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function go(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}function suiteLink(){sessionStorage.setItem('student_code',code.value);location.href='/student/learning-suite'}async function downloadMistakes(){let studentCode=code.value.trim()||sessionStorage.getItem('student_code')||'';if(!studentCode){msg.textContent='أدخل كود الطالب أولًا';return}msg.textContent='جارٍ تجهيز مذكرة الأخطاء...';try{let r=await fetch('/api/student/review/mistakes-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_code:studentCode,max_questions:100})});if(!r.ok){let x=await r.json().catch(()=>null);msg.textContent=typeof x?.detail==='string'?x.detail:'تعذر إنشاء مذكرة الأخطاء';return}let blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='my-mistakes-review.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);msg.textContent='تم تجهيز مذكرة الأخطاء.'}catch(e){msg.textContent='تعذر الاتصال أثناء تجهيز مذكرة الأخطاء. تحقق من الإنترنت وحاول مرة أخرى.'}}async function downloadAttemptFromPortal(attemptId){let studentCode=code.value.trim()||sessionStorage.getItem('student_code')||'';if(!studentCode){msg.textContent='أدخل كود الطالب أولًا';return}msg.textContent='جارٍ تجهيز مراجعة الاختبار...';try{let r=await fetch('/api/student/attempts/'+attemptId+'/review-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({student_code:studentCode,max_questions:100})});if(!r.ok){let x=await r.json().catch(()=>null);msg.textContent=typeof x?.detail==='string'?x.detail:'تعذر إنشاء مراجعة الاختبار';return}let blob=await r.blob(),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='attempt-'+attemptId+'-review.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);msg.textContent='تم تجهيز مراجعة الاختبار.'}catch(e){msg.textContent='تعذر الاتصال أثناء تجهيز مراجعة الاختبار. تحقق من الإنترنت وحاول مرة أخرى.'}}async function load(){msg.textContent='';let r=await fetch('/api/student/portal?student_code='+encodeURIComponent(code.value)),x=await r.json();if(!r.ok){msg.textContent=x.detail||'تعذر الدخول';return}sessionStorage.setItem('student_code',code.value);let d=x.improvement.delta,s=x.learning_suite,rd=s.exam_readiness,t=s.source_grounded_tutor,m=s.mock_exam;content.innerHTML=`<div id=overview class=box><div class=section-title><h2>${esc(x.student.name)}</h2><span class=pill>جاهزية ${rd.score}%</span></div><div class=grid><div class=card><div class=muted>آخر نتيجة</div><div class=big>${x.improvement.latest??'—'}%</div></div><div class=card><div class=muted>التغير</div><div class="big ${d==null?'':d>=0?'good':'bad'}">${d==null?'—':(d>0?'+':'')+d+'%'}</div></div><div class=card><div class=muted>قائمة المراجعة</div><div class=big>${s.spaced_review.count}</div></div><div class=card><div class=muted>الإنجازات</div><div class=big>${s.achievements.count}</div></div></div><p class=${rd.level==='exam_ready'?'good':rd.level==='building'?'warn':''}>${esc(rd.message)}</p><div class=actions><button onclick="suiteLink()">فتح مركز التعلم الذكي</button><button onclick="downloadMistakes()">تنزيل مذكرة أخطائي PDF</button>${m.available?'<button onclick="location.href=\''+m.student_path+'\'">محاكاة امتحان</button>':''}</div></div><div id=plan class=box><h2>خطة المذاكرة الشخصية</h2>${s.personal_study_plan.map(p=>'<div class=card><b>'+p.priority+'. '+esc(p.title)+'</b><div class=muted>'+esc(p.reason)+'</div></div>').join('')}<h3>المدرس المرتبط بالمصدر</h3><div class="card ${t.available?'good':'warn'}">${t.available?'الدرس المستهدف: <b>'+esc(t.lesson_title)+'</b><div class=muted>مصدر الشرح المعتمد: '+esc(t.source.filename)+' · الصفحات '+t.source.start_page+'–'+t.source.end_page+'</div>':esc(t.reason)}</div></div><div class=box><h2>مصدر المنهج الحالي</h2>${x.current_curriculum?'<div class=card><b>المنهج النشط: '+esc(x.current_curriculum.academic_year)+'</b><div class=muted>المصادر: '+x.current_curriculum.source_documents+' · مرشحات الأسئلة: '+x.current_curriculum.total_questions+' · المعتمد: '+x.current_curriculum.approved_questions+' · تحت QA: '+x.current_curriculum.qa_open+' · الاختبارات المنشورة: '+x.current_curriculum.published_quizzes+'</div></div>':''}</div><div id=quizzes class=box><h2>الاختبارات المتاحة</h2>${x.available_quizzes?.length?x.available_quizzes.map(q=>'<div class=card><b>'+esc(q.title)+'</b><div class=muted>'+esc(q.subject_name||'')+' · '+esc(q.grade_name||'')+' · '+esc(q.curriculum_year||'غير محدد')+(q.curriculum_active?' · المنهج الحالي':' · مصدر سابق للمراجعة')+(q.duration_minutes?' · '+q.duration_minutes+' دقيقة':'')+'</div><div class=muted>المحاولات: '+q.attempts_used+' / '+q.max_attempts+' · الدرجة المحتسبة: '+(q.score_policy==='highest'?(q.best_percentage==null?'—':Number(q.best_percentage).toFixed(1)+'%'):(q.latest_percentage==null?'—':Number(q.latest_percentage).toFixed(1)+'%'))+'</div><button '+(!q.has_open_attempt&&q.attempts_used>=q.max_attempts?'disabled':'')+' onclick="location.href=\'/student/quiz/'+q.id+'\'">'+(q.has_open_attempt?'استكمال المحاولة':q.attempts_used>=q.max_attempts?'اكتملت المحاولات':'بدء الاختبار')+'</button></div>').join(''):'<p class=muted>لا توجد اختبارات منشورة متاحة حاليًا.</p>'}</div><div class=box><h2>ماذا أدرس الآن؟</h2>${x.learning_recommendations.recommendations.map((r,i)=>'<div class=card><b>'+(i+1)+'. '+esc(r.title)+'</b><div class=muted>'+esc(r.reason)+'</div>'+(r.action==='adaptive_practice'?'<button onclick="practice()">ابدأ تدريبًا مناسبًا</button>':'')+'</div>').join('')}<div class="card '+(x.learning_recommendations.readiness.ready_for_next?'good':'bad')+'"><b>'+(x.learning_recommendations.readiness.ready_for_next?'جاهز للانتقال':'استمر في التثبيت')+'</b><div class=muted>'+esc(x.learning_recommendations.readiness.reason)+'</div>'+(x.learning_recommendations.readiness.next_lesson?'<div>الدرس التالي: <b>'+esc(x.learning_recommendations.readiness.next_lesson.title)+'</b></div><button onclick="openLesson('+x.learning_recommendations.readiness.next_lesson.id+')">ابدأ الدرس التالي</button>':'')+'</div></div><div id=progress class=box><h2>تحليل نقاط القوة والضعف</h2><div class=grid><div class=card><div class=muted>دروس تحتاج دعم</div><div class=big>${x.mastery.summary.weak_lessons}</div></div><div class=card><div class=muted>مفاهيم تحتاج دعم</div><div class=big>${x.mastery.summary.weak_concepts}</div></div><div class=card><div class=muted>مهارات تحتاج دعم</div><div class=big>${x.mastery.summary.weak_skills}</div></div><div class=card><div class=muted>مفاهيم قوية</div><div class=big>${x.mastery.summary.strong_concepts}</div></div></div>${x.mastery.priority.concepts.length?'<h3>الأولوية الآن</h3>'+x.mastery.priority.concepts.map(v=>'<div class=card><b>'+esc(v.title)+'</b><div class=muted>'+esc(v.lesson_title||'')+' · إتقان '+v.mastery+'% من '+v.responses+' إجابات</div></div>').join(''):''}</div><div class=box><h2>المراجعة المتباعدة</h2>${s.spaced_review.questions.length?s.spaced_review.questions.slice(0,6).map(q=>'<div class=card><b>'+esc(q.lesson_title||'غير مصنف')+'</b><div>'+esc(q.text_verbatim)+'</div><div class=muted>تكرر الخطأ: '+q.wrong_count+' · '+esc(q.source_filename)+' ص'+esc(q.source_page)+'</div></div>').join(''):'<p class=good>لا توجد أخطاء متكررة مؤكدة حاليًا.</p>'}<button onclick="suiteLink()">عرض قائمة المراجعة كاملة</button></div><div class=box><h2>آخر النتائج</h2><table><tr><th>الاختبار</th><th>النتيجة</th><th>التاريخ</th><th>المراجعة</th></tr>${x.attempts.map(a=>'<tr><td>'+esc(a.quiz_title||'اختبار')+'</td><td>'+esc(a.percentage??'—')+'%</td><td>'+esc(a.completed_at||'')+'</td><td><button onclick="downloadAttemptFromPortal('+a.id+')">PDF</button></td></tr>').join('')}</table></div><div class=box><h2>تقدم التدريب العلاجي</h2>${x.remedial_progress?.length?x.remedial_progress.map(c=>'<div class=card><b>'+esc(c.title)+'</b><div class=muted>نتيجة الدورة: '+esc(c.cycle_score??'—')+'% · مفاهيم تحسنت: '+c.improved_concepts+' · مفاهيم قوية: '+c.strong_after+'</div><div class="'+(c.needs_followup?'bad':'good')+'">'+(c.needs_followup?'يحتاج دورة متابعة':'تم إتقان النقاط المستهدفة')+'</div></div>').join(''):'<p class=muted>لم تُسجل دورة تدريب علاجي مكتملة بعد.</p>'}</div>`}function openLesson(id){sessionStorage.setItem('student_code',code.value);location.href='/student/lesson/'+id}async function practice(){let r=await fetch('/api/student/adaptive-practice/create?student_code='+encodeURIComponent(code.value)+'&count=10',{method:'POST'}),x=await r.json();if(!r.ok){msg.textContent=typeof x.detail==='string'?x.detail:JSON.stringify(x.detail);return}location.href=x.student_path}window.addEventListener('DOMContentLoaded',()=>{let saved=sessionStorage.getItem('student_code');if(saved){code.value=saved;load()}})</script></main></html>'''
